use std::sync::{Arc, Barrier};
let barrier = Arc::new(Barrier::new(workers));
std::thread::scope(|s| {
    for id in 0..workers {
        let barrier = Arc::clone(&barrier);
        s.spawn(move || {
            for step in 0..steps {
                compute(id, step);
                if barrier.wait().is_leader() { merge_partials(); }   // exactly once
            }
        });
    }
});
